package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl *template.Template

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	// Template for rendering search results
	tmpl = template.Must(template.New("results").Parse(`
<html><body>
<h2>Product Search Results</h2>
<p>Query: {{.Query}}</p>
<table border="1">
<tr><th>ID</th><th>Name</th><th>Price</th><th>Description</th></tr>
{{range .Products}}
<tr><td>{{.ID}}</td><td>{{.Name}}</td><td>{{.Price}}</td><td>{{.Desc}}</td></tr>
{{end}}
</table>
</body></html>`))
}

type Product struct {
	ID   int
	Name string
	Price float64
	Desc string
}

type SearchResult struct {
	Query    string
	Products []Product
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Basic input length check
	if len(category) > 100 || len(sortBy) > 50 {
		http.Error(w, "Input too long", http.StatusBadRequest)
		return
	}

	// Build query - sort parameter is validated
	allowedSorts := map[string]bool{"price": true, "name": true, "id": true}
	if sortBy == "" || !allowedSorts[sortBy] {
		sortBy = "id"
	}

	// Construct WHERE clause
	conditions := []string{"1=1"}
	if category != "" {
		// Developer note: category is user-controlled, used in LIKE clause
		conditions = append(conditions, fmt.Sprintf("category ILIKE '%%%s%%'", category))
	}
	if minPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price >= %s", minPrice))
	}

	query := fmt.Sprintf("SELECT id, name, price, description FROM products WHERE %s ORDER BY %s LIMIT 50",
		strings.Join(conditions, " AND "), sortBy)

	log.Printf("Executing query: %s", query)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Desc); err != nil {
			continue
		}
		products = append(products, p)
	}

	result := SearchResult{Query: category, Products: products}
	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, result)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
